<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_login();
$rows=db()->query("SELECT r.id,r.name,r.email,r.phone,r.status,r.created_at,(SELECT COUNT(*) FROM plaques p WHERE p.reseller_id=r.id AND p.status='stock') stock_count,(SELECT COUNT(*) FROM plaques p WHERE p.reseller_id=r.id AND p.status='active') activated_count FROM reseller_accounts r ORDER BY r.created_at DESC")->fetchAll();
