?><div class="heading"><div><h1>Revendedores</h1><p>Acompanhe contas e placas vinculadas a cada parceiro.</p></div><a class="button secondary" href="reseller-register.php" target="_blank">Link de cadastro ↗</a></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Revendedor</th><th>E-mail</th><th>Telefone</th><th>Estoque</th><th>Ativadas</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['email'])?></td><td><?=e($r['phone']??'—')?></td><td><?=$r['stock_count']?></td><td><?=$r['activated_count']?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Nenhum revendedor cadastrado.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>